/**
 * Module 5: Mastery
 *
 * Navigate market volatility and master long-term psychology.
 */

import { useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import { useTrainingStore } from '../../../../stores/trainingStore';
import { createSanitizedMarkup } from '../../../../lib/utils/sanitizeHtml';
import type { ScreenContent, QuizOption } from '../types';

const MODULE_5_SCREENS: ScreenContent[] = [
  { id: 'intro', type: 'intro', title: 'Welcome to Module 5: Mastery', subtitle: 'Navigate Volatility and Master Long-term Psychology' },
  { id: 'seven-freedom-facts', type: 'content', title: 'The Seven Freedom Facts', subtitle: 'Truths that liberate you from market fear' },
  { id: 'bear-markets', type: 'content', title: 'Bear Market Navigation', subtitle: 'How to profit from market declines' },
  {
    id: 'market-quiz',
    type: 'quiz',
    title: 'Test Your Market Knowledge',
    question: 'What happens to the S&P 500 in the average 20-year period?',
    options: [
      { value: 'a', label: 'Always goes up steadily', feedback: 'Incorrect! Markets have significant drawdowns.', isCorrect: false },
      { value: 'b', label: 'Experiences at least one 30%+ drop', feedback: 'Correct! Every 20-year period has major declines.', isCorrect: true },
      { value: 'c', label: 'Loses money half the time', feedback: 'Incorrect! Markets rise more than they fall.', isCorrect: false },
      { value: 'd', label: 'Underperforms inflation', feedback: 'Incorrect! Stocks beat inflation long-term.', isCorrect: false },
    ],
    correctAnswer: 'b',
  },
  {
    id: 'crash-scenario',
    type: 'scenario',
    title: 'Market Crash Decision',
    scenario: 'The market drops 30% this month. News is negative everywhere.',
    question: 'What do you do?',
    options: [
      { value: 'sell', label: 'Sell everything to stop losses', feedback: 'Wrong! Locks in losses. The best days often follow the worst days.', isCorrect: false },
      { value: 'hold', label: 'Stay invested and do nothing', feedback: 'Wise! Time in market beats timing the market.', isCorrect: true },
      { value: 'wait', label: 'Wait for signs of recovery before buying', feedback: 'Risky! You will miss the recovery when it comes.', isCorrect: false },
    ],
    correctAnswer: 'hold',
  },
  { id: 'reflection', type: 'reflection', title: 'Personal Mastery Reflection', content: 'Reflect on: How would you react to a 30% market drop? What is your long-term plan?' },
  { id: 'complete', type: 'content', title: 'All 5 Modules Complete!', subtitle: 'You are now a Your Wealth graduate' },
];

function getScreenContent(screen: ScreenContent): string {
  const defaults: Record<string, string> = {
    'seven-freedom-facts': `<h2>The Seven Freedom Facts</h2><ol class="list-decimal ml-8 space-y-2"><li>Markets go up and down cyclically</li><li>Bear markets create buying opportunities</li><li>Time in market beats timing the market</li><li>Missing the best 10 days costs 50% of returns</li><li>Emotional investors buy high and sell low</li><li>Disciplined investors win long-term</li><li>Market volatility is the price of admission</li></ol>`,
    'bear-markets': `<h2>Bear Market Navigation</h2><p>Bear markets are predictable: they happen every 3-5 years. They are also opportunities.</p><p class="mt-4 text-primary-teal font-semibold">Rule: Never sell in a bear market unless you need the money.</p><div class="bg-dark-bg p-4 rounded my-4"><p>During the 2008-2009 crash, those who stayed invested recovered fully by 2012. Those who sold locked in losses forever.</p></div>`,
    'complete': `<h2 class="text-green-400">Congratulations, Graduate!</h2><p>You have completed all 5 Your Wealth modules!</p><h3 class="mt-4">Your Journey:</h3><ul class="list-disc ml-8"><li>Module 1: Foundation - Money psychology</li><li>Module 2: Myth-Busting - Fee destruction</li><li>Module 3: Strategy - Asset allocation</li><li>Module 4: Execution - Advisor selection</li><li>Module 5: Mastery - Market psychology</li></ul><p class="mt-6 text-primary-teal font-bold text-lg">You are now equipped to build lasting wealth.</p>`,
  };
  return defaults[screen.id] || screen.content || '';
}

export default function Module5_Mastery() {
  const navigate = useNavigate();
  const { startModule, recordScreenProgress, completeModule } = useTrainingStore();
  const [currentIndex, setCurrentIndex] = useState(0);
  const [selectedAnswer, setSelectedAnswer] = useState<string | null>(null);
  const [showFeedback, setShowFeedback] = useState(false);
  const currentScreenData = MODULE_5_SCREENS[currentIndex];
  const totalScreens = MODULE_5_SCREENS.length;
  const moduleId = 'module-5-mastery';

  useEffect(() => { startModule(moduleId); }, [moduleId, startModule]);
  const handleAnswerSelect = (answer: string) => { setSelectedAnswer(answer); setShowFeedback(true); };
  const handleNext = () => {
    recordScreenProgress(moduleId, currentScreenData.id, totalScreens);
    const nextIndex = currentIndex + 1;
    if (nextIndex < totalScreens) { setCurrentIndex(nextIndex); setSelectedAnswer(null); setShowFeedback(false); }
    else { completeModule(moduleId); navigate('/training/hub'); }
  };
  const handleBack = () => { currentIndex > 0 ? setCurrentIndex(currentIndex - 1) : navigate('/training/hub'); setSelectedAnswer(null); setShowFeedback(false); };
  const progress = ((currentIndex + 1) / totalScreens) * 100;

  return (
    <div className="min-h-screen bg-gradient-to-br from-dark-bg to-dark-surface py-12 px-4">
      <div className="max-w-4xl mx-auto">
        <div className="mb-6"><div className="w-full bg-dark-bg rounded-full h-2"><div className="bg-primary-teal h-2 rounded-full transition-all" style={{ width: `${progress}%` }} /></div></div>
        <div className="bg-dark-surface border border-dark-border rounded-lg p-8">
          {currentScreenData.title && <h1 className="text-3xl font-bold text-white mb-2">{currentScreenData.title}</h1>}
          {currentScreenData.subtitle && <p className="text-xl text-primary-teal mb-6">{currentScreenData.subtitle}</p>}
          {(currentScreenData.type === 'content' || currentScreenData.type === 'intro' || currentScreenData.type === 'reflection') && (
            <div className="text-gray-300 leading-relaxed prose prose-invert max-w-none" dangerouslySetInnerHTML={createSanitizedMarkup(getScreenContent(currentScreenData))} />
          )}
          {(currentScreenData.type === 'quiz' || currentScreenData.type === 'scenario') && currentScreenData.options && (
            <div className="mt-8 space-y-3">
              {currentScreenData.options.map((option: QuizOption) => (
                <button key={option.value} onClick={() => handleAnswerSelect(option.value)} disabled={showFeedback}
                  className={`w-full text-left px-6 py-4 rounded-lg border transition-all ${
                    selectedAnswer === option.value ? (showFeedback && option.isCorrect ? 'bg-green-400/20 border-green-400' : showFeedback ? 'bg-red-400/20 border-red-400' : 'bg-primary-teal/20 border-primary-teal') : 'bg-dark-bg border-dark-border hover:border-primary-teal'
                  }`}>
                  <span className="text-gray-200 font-semibold">{option.label}</span>
                </button>
              ))}
            </div>
          )}
          {showFeedback && selectedAnswer && currentScreenData.options && (
            <div className={`mt-6 p-4 rounded-lg border ${selectedAnswer === currentScreenData.correctAnswer ? 'bg-green-400/10 border-green-400/30' : 'bg-red-400/10 border-red-400/30'}`}>
              <p className="text-gray-300">{currentScreenData.options.find((o: QuizOption) => o.value === selectedAnswer)?.feedback || ''}</p>
            </div>
          )}
          {(currentScreenData.type === 'intro' || currentScreenData.type === 'content' || currentScreenData.type === 'quiz' || currentScreenData.type === 'scenario') && (
            <div className="flex justify-between items-center mt-8">
              <button onClick={handleBack} className="px-6 py-3 rounded-lg border border-dark-border text-gray-300 hover:border-gray-500 font-semibold">← Back</button>
              <button onClick={handleNext} disabled={(currentScreenData.type === 'quiz' || currentScreenData.type === 'scenario') && !showFeedback} className="px-6 py-3 rounded-lg bg-primary-teal hover:bg-teal-600 text-white font-semibold disabled:bg-gray-700">{currentIndex === totalScreens - 1 ? 'Complete' : 'Next'} →</button>
            </div>
          )}
          {currentScreenData.type === 'reflection' && (
            <div className="flex justify-between items-center mt-8">
              <button onClick={handleBack} className="px-6 py-3 rounded-lg border border-dark-border text-gray-300 hover:border-gray-500 font-semibold">← Back</button>
              <button onClick={handleNext} className="px-6 py-3 rounded-lg bg-primary-teal hover:bg-teal-600 text-white font-semibold">Continue →</button>
            </div>
          )}
        </div>
      </div>
    </div>
  );
}
